SELECT 
FROM report_record
WHERE del_flag = 0
           AND type = #{type}
  AND hazard_point_id = #{hazardPointId}
    AND period_start >= #{periodStart}
      AND period_end   <= #{periodEnd}
         AND status = #{status}

    AND report_name LIKE CONCAT('%', #{keyword}, '%')

ORDER BY create_time DESC

SELECT COUNT(*) FROM report_record
WHERE del_flag = 0
           AND type = #{type}
  AND hazard_point_id = #{hazardPointId}
    AND period_start >= #{periodStart}
      AND period_end   <= #{periodEnd}
         AND status = #{status}

    AND report_name LIKE CONCAT('%', #{keyword}, '%')

SELECT 
FROM report_record
WHERE type = #{type}
  AND hazard_point_id = #{hazardPointId}
  AND period_start = #{periodStart}
  AND period_end = #{periodEnd}
  AND status = 2
  AND del_flag = 0
LIMIT 1
